public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int row = Integer.parseInt(sc.next());
    int column = Integer.parseInt(sc.next());

    List<String> s = new ArrayList<>();
    for (int i = 0; i < row; i++) {
        s.add(sc.next());
    }

    int vertex = row * column;

    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < vertex; i++) {
        graph.add(new ArrayList<>());
    }

    List<Boolean> troutInInfluence = new ArrayList<>();
    for (int i = 0; i < vertex; i++) {
        troutInInfluence.add(false);
    }

    for (int i = 0; i < row; i++) {
        for (int j = 0; j < column; j++) {
            if (s.get(i).charAt(j) == '#') {
                int index = i * column + j;
                troutInInfluence.set(index, true);
                if (i > 0) troutInInfluence.set((i - 1) * column + j, true);
                if (i < row - 1) troutInInfluence.set((i + 1) * column + j, true);
                if (j > 0) troutInInfluence.set(i * column + (j - 1), true);
                if (j < column - 1) troutInInfluence.set(i * column + (j + 1), true);
            }
        }
    }

    for (int i = 0; i < row; i++) {
        for (int j = 0; j < column; j++) {
            if (!troutInInfluence.get(i * column + j)) {
                if (i > 0 && !troutInInfluence.get((i - 1) * column + j)) {
                    graph.get(i * column + j).add((i - 1) * column + j);
                }
                if (i < row - 1 && !troutInInfluence.get((i + 1) * column + j)) {
                    graph.get(i * column + j).add((i + 1) * column + j);
                }
                if (j > 0 && !troutInInfluence.get(i * column + (j - 1))) {
                    graph.get(i * column + j).add(i * column + (j - 1));
                }
                if (j < column - 1 && !troutInInfluence.get(i * column + (j + 1))) {
                    graph.get(i * column + j).add(i * column + (j + 1));
                }
            }
        }
    }

    List<Boolean> used = new ArrayList<>();
    for (int i = 0; i < vertex; i++) {
        used.add(false);
    }

    List<Integer> last = new ArrayList<>();
    for (int i = 0; i < vertex; i++) {
        last.add(0);
    }

    int time = 0;
    int ans = 1;

    for (int i = 0; i < vertex; i++) {
        if (!troutInInfluence.get(i)) {
            if (used.get(i)) {
                continue;
            }
            time++;
            int cnt = 0;
            Queue<Integer> queue = new LinkedList<>();
            queue.add(i);
            used.set(i, true);
            while (!queue.isEmpty()) {
                int position = queue.remove();
                cnt++;
                for (int next : graph.get(position)) {
                    if (used.get(next)) {
                        continue;
                    }
                    if (troutInInfluence.get(next)) {
                        if (last.get(next) != time) {
                            cnt++;
                            last.set(next, time);
                        }
                        continue;
                    }
                    queue.add(next);
                    used.set(next, true);
                }
            }
            ans = Math.max(ans, cnt);
        }
    }
    System.out.println(ans);
}
